import type { AuthSession } from "@jcoder-stack/abp-react/auth";
import { HUB_NAME_PATTERN, type HubConnectionInfo } from "@jcoder-stack/abp-react/realtime";
import { z } from "zod";

export const hubInputSchema = z.object({ hub: z.string().regex(HUB_NAME_PATTERN) });

/** ABP maps hubs under this path unless the backend sets AbpSignalROptions otherwise. */
export const DEFAULT_HUB_PREFIX = "/signalr-hubs";

/**
 * Derives what the browser needs to open `hub`. The URL is built here, on the server, from the
 * backend origin the BFF already trusts, so the client never names an arbitrary host.
 */
export function hubConnectionInfo(opts: {
  session: AuthSession | null;
  abpBaseUrl: string;
  hubPrefix: string | undefined;
  hub: string;
}): HubConnectionInfo | null {
  if (opts.session === null) return null;
  const trimmed = opts.hubPrefix?.trim().replace(/^\/+|\/+$/g, "") ?? "";
  const prefix = trimmed === "" ? DEFAULT_HUB_PREFIX : `/${trimmed}`;
  return {
    url: `${opts.abpBaseUrl.replace(/\/+$/, "")}${prefix}/${opts.hub}`,
    accessToken: opts.session.tokens.accessToken,
    expiresAt: opts.session.expiresAt ?? null,
  };
}

import { createServerFn } from "@tanstack/react-start";
import { authMiddleware } from "@/auth/middleware";
import { getAuthRuntime } from "@/auth/runtime";
import { hubConnectionInfo, hubInputSchema } from "@/features/signalr/hub-connection-info";

/**
 * Hands the signed-in browser a short-lived token for one SignalR hub: the single, bounded
 * exception to "tokens never reach the browser" (docs/architecture.md). authMiddleware refreshes
 * an expiring session first, so the token handed out is always fresh. Anonymous visitors get null.
 */
export const getHubConnectionInfoFn = createServerFn({ method: "GET" })
  .validator(hubInputSchema)
  .middleware([authMiddleware])
  .handler(({ data, context }) =>
    hubConnectionInfo({
      session: context.session,
      abpBaseUrl: getAuthRuntime().env.abpBaseUrl,
      // 不进应用的 src/env.ts：那个文件归应用所有，功能安装不改它。
      hubPrefix: process.env.SIGNALR_HUB_PREFIX,
      hub: data.hub,
    }),
  );

import { RealtimeProvider } from "@jcoder-stack/abp-react/realtime";
import type { ReactNode } from "react";
import type { FeatureModule } from "@/features/compose";
import { NotificationToaster } from "@/features/signalr/notifications";
import notificationsMessages from "@/features/signalr/notifications-messages.json";
import { getHubConnectionInfoFn } from "@/features/signalr/server-fns";

/** Module level: RealtimeProvider reads it once and needs one stable reference. */
const getConnectionInfo = (hub: string) => getHubConnectionInfoFn({ data: { hub } });

function SignalRProvider({ children }: { children: ReactNode }) {
  return (
    <RealtimeProvider getConnectionInfo={getConnectionInfo}>
      <NotificationToaster />
      {children}
    </RealtimeProvider>
  );
}

const signalr: FeatureModule = { Provider: SignalRProvider, messages: notificationsMessages };

export default signalr;

import { z } from "zod";

/** Plain text, or a localization key resolved in the browser so each recipient sees their own language. */
export type LocalizableText =
  | string
  | { key: string; resource?: string; args?: Record<string, string> };

export type NotificationSeverity = "info" | "success" | "warning" | "error";

export interface AppNotification {
  id: string;
  severity: NotificationSeverity;
  title: LocalizableText;
  message?: LocalizableText;
  url?: string;
}

/**
 * Same-origin paths only: `//host` and `/\host` are protocol-relative in browsers, i.e. an open
 * redirect. Browsers also strip tab/CR/LF before parsing, so `/<tab>/host` is protocol-relative
 * too; any control character, space or DEL is therefore rejected.
 */
export function isSafeRelativeUrl(url: string): boolean {
  return (
    url.startsWith("/") &&
    !url.startsWith("//") &&
    !url.startsWith("/\\") &&
    !hasControlOrSpace(url)
  );
}

function hasControlOrSpace(text: string): boolean {
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i);
    if (code <= 0x20 || code === 0x7f) return true;
  }
  return false;
}

const localizableText = z.union([
  z.string(),
  z.object({
    key: z.string().min(1),
    resource: z.string().optional(),
    args: z.record(z.string(), z.string()).optional(),
  }),
]);

const notificationSchema = z.object({
  id: z.string().min(1),
  severity: z.enum(["info", "success", "warning", "error"]).catch("info"),
  title: localizableText,
  message: localizableText.optional().catch(undefined),
  url: z.string().refine(isSafeRelativeUrl).optional().catch(undefined),
});

/**
 * Tolerant parse of a `ReceiveNotification` payload: an unknown severity becomes info and a bad
 * message or url is dropped, but without an id and a title there is nothing to show (null).
 */
export function parseNotification(raw: unknown): AppNotification | null {
  const parsed = notificationSchema.safeParse(raw);
  if (!parsed.success) return null;
  const { id, severity, title, message, url } = parsed.data;
  return {
    id,
    severity,
    title,
    ...(message === undefined ? {} : { message }),
    ...(url === undefined ? {} : { url }),
  };
}

export function localizeText(
  text: LocalizableText,
  L: (key: string, ...args: unknown[]) => string,
): string {
  if (typeof text === "string") return text;
  const key = text.resource === undefined ? text.key : `${text.resource}::${text.key}`;
  return text.args === undefined ? L(key) : L(key, text.args);
}

import { createLogger } from "@jcoder-stack/abp-react/logger";
import { useLocalization } from "@jcoder-stack/abp-react/react";
import { useHubEvent } from "@jcoder-stack/abp-react/realtime";
import { useRouter } from "@tanstack/react-router";
import { toast } from "sonner";
import {
  type AppNotification,
  localizeText,
  parseNotification,
} from "@/features/signalr/notification";

export const NOTIFICATIONS_HUB = "notifications";
export const RECEIVE_NOTIFICATION = "ReceiveNotification";

const logger = createLogger({ scope: "realtime:notifications" });

/** Runs `handler` for every well-formed notification pushed to the signed-in user; malformed ones are dropped. */
export function useNotificationEvent(handler: (notification: AppNotification) => void): void {
  useHubEvent(NOTIFICATIONS_HUB, RECEIVE_NOTIFICATION, (raw) => {
    const notification = parseNotification(raw);
    if (notification === null) {
      logger.debug("dropped a malformed notification");
      return;
    }
    handler(notification);
  });
}

/**
 * Shows each pushed notification as a toast at its severity, with a View action when it carries a
 * url. Edit this file to change how notifications look; it is yours once installed.
 */
export function NotificationToaster(): null {
  const L = useLocalization();
  const router = useRouter();
  useNotificationEvent((notification) => {
    const { url } = notification;
    toast[notification.severity](localizeText(notification.title, L), {
      // 同一 id 再到达时 sonner 原地更新，不叠第二条。
      id: notification.id,
      description:
        notification.message === undefined ? undefined : localizeText(notification.message, L),
      action:
        url === undefined
          ? undefined
          : {
              label: L("Notifications:View"),
              // url 来自后端运行时，编译期无从校验，所以不用 typed Link。
              onClick: () => void router.navigate({ href: url }),
            },
    });
  });
  return null;
}
